SELECT CAST(COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate, CAST(COUNT(DISTINCT CASE WHEN p.dod IS NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS prevalence_rate, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS num_deaths, SUM(CASE WHEN p.dod IS NULL THEN 1 ELSE 0 END) AS num_alive FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN icustays i ON a.subject_id = i.subject_id WHERE p.gender = 'M' AND p.anchor_age = 58 AND p.anchor_year_group BETWEEN 53 AND 63 AND i.intime <= '2020-01-01' AND i.outtime >= '2020-12-31' AND i.los <= 8 AND i.first_careunit = 'ICU' AND i.last_careunit = 'ICU' AND i.stay_id IN (SELECT stay_id FROM chartevents WHERE itemid IN (SELECT itemid FROM labevents WHERE value = 'Sepsis'));